<div class="page-title"><div><em>SYSTEM</em><h1>System settings</h1><p>Configure platform-wide banking preferences, announcements and SEO.</p></div></div><div class="grid settings-grid"><nav class="panel settings-nav"><a class="active" data-tab="general">▥ General</a><a data-tab="seo">◎ SEO &amp; announcements</a><a href="<?=site_url('admin/admin_users')?>">♙ Admin users</a></nav><section class="panel settings-form"><div class="tab active" data-panel="general"><h2>General settings</h2><p>Manage platform identity and operational preferences.</p><?=form_open('admin/settings')?><label>Institution name</label><input name="institution_name" value="<?=html_escape($settings['institution_name']??'NorthWest Financial Ltd.')?>"><div class="form-grid"><div><label>Support email</label><input name="support_email" type="email" value="<?=html_escape($settings['support_email']??'')?>"></div><div><label>Default currency</label><select name="default_currency"><option>USD</option><option>EUR</option><option>GBP</option></select></div><div><label>Daily transfer limit</label><input name="daily_transfer_limit" type="number" value="<?=html_escape($settings['daily_transfer_limit']??'25000')?>"></div><div><label>Session timeout (minutes)</label><input name="session_timeout" type="number" value="<?=html_escape($settings['session_timeout']??'15')?>"></div></div><div class="form-grid"><div><label>Bank routing number</label><input name="routing_number" value="<?=html_escape($settings['routing_number']??'021000021')?>" maxlength="9"></div><div><label>International fee (%)</label><input name="international_fee_percent" type="number" step="0.01" min="0" value="<?=html_escape($settings['international_fee_percent']??'1.5')?>"></div><div><label>International flat fee</label><input name="international_fee_flat" type="number" step="0.01" min="0" value="<?=html_escape($settings['international_fee_flat']??'0')?>"></div></div><label class="pref-row"><span><b>Public registration</b><small>Allow customers to create accounts online</small></span><input type="hidden" name="registration_enabled" value="0"><input type="checkbox" name="registration_enabled" value="1" <?=($settings['registration_enabled']??'0')==='1'?'checked':''?>></label><label>Announcement bar text</label><textarea name="announcement_text" rows="3" placeholder="Shown in the moving bar at the top of every page."><?=html_escape($settings['announcement_text']??'')?></textarea><small class="field-hint">This text scrolls across the top announcement bar (black on white) on every page.</small><button class="btn">Save settings</button></form></div><div class="tab" data-panel="seo"><h2>SEO &amp; announcements</h2><p>Improve how NorthWest appears in search engines and social sharing.</p><?=form_open('admin/settings')?><label>Site name</label><input name="seo_site_name" value="<?=html_escape($settings['seo_site_name']??'NorthWest Financial')?>" placeholder="NorthWest Financial"><label>Default page title</label><input name="seo_title" value="<?=html_escape($settings['seo_title']??'NorthWest Financial — Secure Online Banking')?>"><label>Meta description</label><textarea name="seo_description" rows="3" placeholder="Short summary shown in search results (150–160 characters)."><?=html_escape($settings['seo_description']??'')?></textarea><label>Keywords</label><input name="seo_keywords" value="<?=html_escape($settings['seo_keywords']??'')?>" placeholder="online banking, secure banking, transfers"><p class="seo-preview">Preview: <code>&lt;meta name="description" content="…"&gt;</code>, Open Graph and Twitter tags are rendered automatically in the page head.</p><button class="btn">Save SEO settings</button></form></div></section></div>
<script>document.querySelectorAll('[data-tab]').forEach(function(tab){tab.addEventListener('click',function(){document.querySelectorAll('[data-tab]').forEach(function(t){t.classList.toggle('active',t===tab)});document.querySelectorAll('[data-panel]').forEach(function(p){p.classList.toggle('active',p.getAttribute('data-panel')===tab.getAttribute('data-tab'))})})});</script>
